}
.dark [data-workspace-area="conversation"]::after {
  --lane: calc(50% + (var(--chat-lane-inset-start, 0px) - var(--chat-lane-inset-end, 0px)) / 2);
  --half: calc(var(--chat-content-max-width, 46rem) / 2);
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  backdrop-filter: blur(3px);
  mask-image: linear-gradient(90deg, transparent calc(var(--lane) - var(--half) - 8rem), #000 calc(var(--lane) - var(--half)),
    #000 calc(var(--lane) + var(--half)), transparent calc(var(--lane) + var(--half) + 8rem));
}
.dark [data-workspace-area="conversation"] > div,
.dark .messages-timeline-scroll { background: transparent !important; }
.dark [data-slot="composer-host"] { background: rgba(30, 32, 48, .7) !important; backdrop-filter: blur(10px); }
